typedef struct Node {
    int v;
    struct Node*next;
} Node;
Node* removeNth(Node*head, int n) {
    Node d;
    d.next=head;
    Node*f=&d, *s=&d;
    for (int i=0; i<=n; i++)f=f->next;
    while (f) {
        s=s->next;
        f=f->next;
    }
    s->next=s->next->next;
    return d.next;
}

